H.background();
const v = H.plot2d({ xMin: -6, xMax: 6, yMin: -8, yMax: 8 });
v.grid(); v.axes();
const m = P.m, b = P.b;
const f = (x) => m * x + b;
const g = (x) => Math.sin(x) + 1;
const op = Math.round(P.op);
const opNames = ["(f+g)(x)", "(f-g)(x)", "(f*g)(x)", "(f/g)(x)"];
const combine = (x) => {
  if (op === 1) return f(x) + g(x);
  if (op === 2) return f(x) - g(x);
  if (op === 3) return f(x) * g(x);
  const d = g(x);
  return Math.abs(d) > 1e-3 ? f(x) / d : NaN;
};
const idx = Math.max(0, Math.min(3, op - 1));
v.fn(f, { color: H.colors.sub, width: 1.5 });
v.fn(g, { color: H.colors.violet, width: 1.5 });
v.fn(combine, { color: H.colors.accent, width: 3 });
